type Err = (ParseErrorKind, usize, usize); // (kind, start, length)

fn check(src: &str, expected_tree: &str, expected_errors: &[Err]) {
    let tokens = tokenize(src);
    let ast = parse(&tokens, src);
    assert_eq!(shape(&ast), expected_tree, "tree for {src:?}");
    let mut errs: Vec<Err> = ast
        .errors
        .iter()
        .map(|e| (e.kind, e.span.start, e.span.length))
        .collect();
    errs.sort_by_key(|&(_, start, len)| (start, len)); // stable
    assert_eq!(errs, expected_errors, "errors for {src:?}");
}

fn ok(src: &str, expected_tree: &str) {
    check(src, expected_tree, &[]);
}

/// Render the tree as a compact s-expression string.
///   Root      -> "<" children joined by " " ">"
///   List      -> "(" children joined by " " ")"
///   Quote     -> "'" + child
///   Cons      -> "(" head " . " tail ")"
///   Symbol    -> source text exactly as written
///   Integer   -> value via {}      e.g. 42, -7
///   Real      -> value via {:?}    e.g. 3.5, 3.0, 2147483648.0
///   String    -> source slice verbatim, quotes included
///                (an unterminated string has no closing quote)
fn shape(_ast: &Ast) -> String {
    todo!("recursive match over your node kinds")
}

