#[test]
fn empty_source() {
    ok("", "<>");
}

#[test]
fn only_trivia_is_empty_root() {
    ok("  ; hi\n;| x |;\n\t", "<>");
}

#[test]
fn single_symbol() {
    ok("a", "<a>");
}

#[test]
fn multiple_top_level_forms() {
    ok("a b\nc", "<a b c>");
}

#[test]
fn empty_list() {
    ok("()", "<()>");
}

#[test]
fn flat_list() {
    ok("(a b)", "<(a b)>");
}

#[test]
fn nested_lists() {
    ok("(a (b (c)) d)", "<(a (b (c)) d)>");
}

#[test]
fn trivia_is_dropped_inside_lists() {
    ok("(a ; hi\n b ;| x |; c)", "<(a b c)>");
}

#[test]
fn symbol_case_is_preserved() {
    ok("(DefUn f ())", "<(DefUn f ())>");
}

