// ---------------------------------------------------------------
// spans
// ---------------------------------------------------------------

#[test]
fn spans_list_and_quote() {
    // "  (a 'b)"  -> '(' at 2, 'a' at 3, quote at 5, 'b' at 6, ')' at 7
    assert_eq!(
        outline("  (a 'b)"),
        [
            ("root", 0, 8),
            ("list", 2, 6),
            ("sym", 3, 1),
            ("quote", 5, 2),
            ("sym", 6, 1),
        ]
    );
}

#[test]
fn spans_cons() {
    assert_eq!(
        outline("(a . b)"),
        [("root", 0, 7), ("cons", 0, 7), ("sym", 1, 1), ("sym", 5, 1)]
    );
}

#[test]
fn spans_literals() {
    assert_eq!(
        outline("(12 3.5 \"s\")"),
        [
            ("root", 0, 12),
            ("list", 0, 12),
            ("int", 1, 2),
            ("real", 4, 3),
            ("str", 8, 3),
        ]
    );
}

#[test]
fn spans_are_in_bytes_not_chars() {
    // 'é' is two bytes: string is bytes 1..5, x is at 6
    assert_eq!(
        outline("(\"é\" x)"),
        [("root", 0, 8), ("list", 0, 8), ("str", 1, 4), ("sym", 6, 1)]
    );
}

#[test]
fn root_span_covers_trailing_trivia() {
    assert_eq!(outline("a  "), [("root", 0, 3), ("sym", 0, 1)]);
}

#[test]
fn spans_are_well_nested_on_realistic_source() {
    assert_well_nested(";; header\n(defun c:foo (/ a)\n  (setq a '(1 . 2)) ; t\n  (princ))\n");
}

#[test]
fn spans_are_well_nested_on_broken_source() {
    assert_well_nested("(a (b (c\n(defun f ()))) \"x");
}

