// ---------------------------------------------------------------
// recovery: unclosed '('
// ---------------------------------------------------------------

#[test]
fn unclosed_list_at_eof() {
    check("(a b", "<(a b)>", &[(UnclosedList, 4, 0)]);
    // recovered list ends where the ')' should have been
    assert_eq!(outline("(a b")[1], ("list", 0, 4));
}

#[test]
fn unclosed_error_sits_after_last_non_trivia_token() {
    // not after the trailing spaces, comment, or newlines
    check("(a b  ; hi\n\n", "<(a b)>", &[(UnclosedList, 4, 0)]);
    assert_eq!(outline("(a b  ; hi\n\n")[1], ("list", 0, 4));
}

#[test]
fn unclosed_list_closed_by_defun_at_line_start() {
    let src = "(setq a 1\n(defun f () 1)";
    check(src, "<(setq a 1) (defun f () 1)>", &[(UnclosedList, 9, 0)]);
    let o = outline(src);
    assert_eq!(o[1], ("list", 0, 9));
}

#[test]
fn defun_variants_are_recovery_points_case_insensitively() {
    for name in [
        "defun",
        "DEFUN",
        "DeFuN",
        "defun-q",
        "DEFUN-Q",
        "defun-q-list-set",
        "defun-q-list-ref",
    ] {
        let src = format!("(a\n({name} f ())");
        let expected = format!("<(a) ({name} f ())>");
        check(&src, &expected, &[(UnclosedList, 2, 0)]);
    }
}

#[test]
fn similar_names_are_not_recovery_points() {
    check(
        "(a\n(defunx f ())",
        "<(a (defunx f ()))>",
        &[(UnclosedList, 16, 0)],
    );
    check(
        "(a\n(setq b 1)",
        "<(a (setq b 1))>",
        &[(UnclosedList, 13, 0)],
    );
}

#[test]
fn defun_not_at_line_start_does_not_recover() {
    // mid-line
    check(
        "(a (defun f ()) b",
        "<(a (defun f ()) b)>",
        &[(UnclosedList, 17, 0)],
    );
    // indented (ASSUMPTION: "line start" means column 0)
    check(
        "(a\n  (defun f ())",
        "<(a (defun f ()))>",
        &[(UnclosedList, 17, 0)],
    );
}

#[test]
fn nested_unclosed_lists_all_close_at_same_point_innermost_first() {
    let src = "(a (b (c\n(defun f ())";
    check(
        src,
        "<(a (b (c))) (defun f ())>",
        &[
            (UnclosedList, 8, 0),
            (UnclosedList, 8, 0),
            (UnclosedList, 8, 0),
        ],
    );
    let lists: Vec<_> = outline(src).into_iter().filter(|n| n.0 == "list").collect();
    assert_eq!(lists[..3], [("list", 0, 8), ("list", 3, 5), ("list", 6, 2)]);
}

#[test]
fn column_zero_defun_inside_balanced_list_follows_literal_rule() {
    // DESIGN QUESTION: the list below is balanced, but a column-0 `(defun`
    // is treated as a hard boundary, so `(progn` is "unclosed" and the real
    // `)` becomes a stray. Flip this test if you want a balance pre-check.
    check(
        "(progn\n(defun f () 1)\n)",
        "<(progn) (defun f () 1)>",
        &[(UnclosedList, 6, 0), (UnmatchedCloseParen, 22, 1)],
    );
}

