fn stray_close_alone() {
    check(")", "<>", &[(UnmatchedCloseParen, 0, 1)]);
}

#[test]
fn stray_close_between_forms() {
    check("a ) b", "<a b>", &[(UnmatchedCloseParen, 2, 1)]);
}

