#[test]
fn never_panics_on_garbage() {
    for s in [
        "\"", ";|", "\\", ")(", "'", ".", "\u{0}", "\r\n\r\n", "|;", "é", "-", "((((", "(a . ",
        "(. a)", "( ' ", "))))", "'(", "(defun", "\n(defun",
    ] {
        let tokens = tokenize(s);
        let _ = parse(&tokens, s);
    }
}

